            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#a6adb6",
                "fontSize": "custom",
                "customFontSize": 15,
                "markdown": "Compares selected-window ISE RADIUS and TACACS+ policy-set hit activity. Stacked columns show how each policy family contributes over time."
            }
        },
